def solve(n):
    flags = [True] * (n + 1)
    if n >= 0: flags[0] = False
    if n >= 1: flags[1] = False
    p = 2
    while p * p <= n:
        if flags[p]:
            for multiple in range(p * p, n + 1, p): flags[multiple] = False
        p += 1
    return [i for i in range(2, n + 1) if flags[i]]
